    private static void pick(AssetImportDialog ui,EditorTopologyProject project)throws Exception{
        ((JComboBox<?>)field(ui,"selectionMode")).setSelectedItem("FACE");var triangle=project.mesh().triangles().get(0);var p=camera(ui).project((triangle.a().x()+triangle.b().x()+triangle.c().x())/3,(triangle.a().y()+triangle.b().y()+triangle.c().y())/3,(triangle.a().z()+triangle.b().z()+triangle.c().z())/3);var view=viewport(ui);int x=(Integer)call(view,"x",new Class<?>[]{double.class},p.x()),y=(Integer)call(view,"y",new Class<?>[]{double.class},p.y());var canvas=(JPanel)field(ui,"preview");event(canvas,MouseEvent.MOUSE_PRESSED,x,y,1);event(canvas,MouseEvent.MOUSE_RELEASED,x,y,1);check(((EditorMeshPicking.Hit)field(ui,"selectedHit")).faceId()==0,"Actual 3D click anchors native surface face");
    }
