            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();button(dock,"applyFaceEdit");rotated.set(project.get().snapshot());near(project.get().frame("panel").vector(0).y(),1);near(rotated.get().vertices().get(0).y(),1);}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();pick(dock,project.get());((JComboBox<?>)field(dock,"transformSpace")).setSelectedIndex(2);check(((JComboBox<?>)field(dock,"transformSpace")).isShowing(),"Local controls visible in their actual model inspector");((JComboBox<?>)field(dock,"transformKind")).setSelectedItem(EditorTopologyProject.Transform.SCALE_AXIS);((JComboBox<?>)field(dock,"transformAxis")).setSelectedIndex(0);((JComboBox<?>)field(dock,"transformPivot")).setSelectedIndex(1);((JSpinner)field(dock,"transformAmount")).setValue(2d);button(dock,"previewTransform");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var candidate=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");check(project.get().snapshot()==rotated.get()&&candidate.description().contains("local X"),"Human local-axis preview preserves live geometry/frame");near(candidate.snapshot().vertices().get(0).x(),0);near(candidate.snapshot().vertices().get(0).y(),2);capture(dock,output.resolve("human-local-preview.png"));button(dock,"cancelFaceEdit");check(project.get().snapshot()==rotated.get(),"Local Cancel preserves native frame");button(dock,"previewTransform");}catch(Exception e){throw new RuntimeException(e);}});await(()->reviewed(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();var candidate=(EditorTopologyProject.EditPreview)field(dock,"modelingPreview");button(dock,"applyFaceEdit");scaled.set(project.get().snapshot());check(scaled.get()==candidate.snapshot(),"Apply exact local geometry/frame candidate");near(project.get().frame("panel").vector(0).y(),2);button(dock,"undoMesh");check(project.get().snapshot().equals(rotated.get()),"Local geometry and frame one-step undo");button(dock,"redoMesh");check(project.get().snapshot().equals(scaled.get()),"Local geometry/frame exact redo");button(dock,"saveMesh");button(dock,"reopenMesh");check(EditorTopologyProject.open(project.get().documentPath()).snapshot().equals(project.get().snapshot()),"Actual native v5 save/reopen retains local orientation and scale");}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
            SwingUtilities.invokeAndWait(()->{try{var dock=ui.get();pick(dock,project.get());Object handle=null;for(var h:(List<?>)get(dock,"gizmoHandles"))if(((Number)get(h,"axis")).intValue()==0)handle=h;check(handle!=null,"Persisted local X gizmo exists after reopen");var direction=(EditorMeshPipeline.Normal)get(handle,"direction");near(direction.x(),0);near(direction.y(),2);near(direction.z(),0);int x=(Integer)get(handle,"x"),y=(Integer)get(handle,"y");double wx=number(handle,"worldX"),wy=number(handle,"worldY"),wz=number(handle,"worldZ"),scale=number(handle,"scale");var cam=(EditorMeshPicking.Projector)get(handle,"camera");var a=cam.project(wx,wy,wz);var b=cam.project(wx+direction.x()*.25,wy+direction.y()*.25,wz+direction.z()*.25);drag((JPanel)field(dock,"preview"),1,x,y,(int)Math.round((b.x()-a.x())*scale),(int)Math.round((b.y()-a.y())*scale));}catch(Exception e){throw new RuntimeException(e);}});await(()->ready(ui.get()));
